// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

/* Equal: the comparison returns exactly zero. */
static void agent_strncasecmp_zero_len(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "abc", 0), 0);
}

static void agent_strncasecmp_identical(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 32), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "a", 1), 0);
}

static void agent_strncasecmp_case_insensitive_equal(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("HELLO", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "A", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "z", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a_B-9", "A_b-9", 5), 0);
}

static void agent_strncasecmp_ordering(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("b", "a", 1), 0);
	/* Case folding: 'B' sorts after 'a' */
	KUNIT_EXPECT_GT(test, strncasecmp("B", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("A", "b", 1), 0);
}

/* The return value is the difference of the folded characters. */
static void agent_strncasecmp_exact_difference(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "c", 1), -2);
	KUNIT_EXPECT_EQ(test, strncasecmp("C", "a", 1), 2);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "B", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("xyZ", "xyA", 3), 25);
}

/* Only the first len characters are compared. */
static void agent_strncasecmp_len_limits_compare(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "abcY", 3), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("abcX", "abcY", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "abcY", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdefg", "abcdefz", 6), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("abcdefg", "abcdefz", 7), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("xxxxA", "xxxxb", 5), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("xxxxA", "xxxxb", 5), 0);
}

/* Off-by-one checks at len == length of the strings. */
static void agent_strncasecmp_len_boundary(struct kunit *test)
{
	/* Equal when len covers exactly the common prefix */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 2), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);

	/* Shorter string: the terminator is compared when len allows it */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abc", 4), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abc", 3), 0);
}

static void agent_strncasecmp_prefix(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcdef", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcdef", "abc", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("AB", "abc", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abc", "AB", 3), 0);
}

static void agent_strncasecmp_empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "A", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("Q", "", 5), 0);
}

/* A NUL in either string ends the comparison even if len is larger. */
static void agent_strncasecmp_embedded_nul(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0x", "ab\0y", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab\0x", "AB", 8), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ab\0y", 8), 0);
}

/* Non-letters must not be folded: '[' is 0x5b, 'Z' folds to 'z' (0x7a). */
static void agent_strncasecmp_non_letters(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("Z", "[", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("[", "z", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("`", "@", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("0123", "0123", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("9", "A", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("{", "[", 1), 0);
}

/* Bytes >= 0x80 must compare as unsigned characters. */
static void agent_strncasecmp_high_bytes(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "\xff", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("\xc3\xa9", "\xc3\xa9", 2), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("\xc3\xa9", "\xc3\x89", 2), 0);
}

/* Long strings: the mismatch must be found exactly at the len boundary. */
static void agent_strncasecmp_long_boundary(struct kunit *test)
{
	char s1[65];
	char s2[65];

	memset(s1, 'Q', 64);
	memset(s2, 'q', 64);
	s1[64] = '\0';
	s2[64] = '\0';
	s2[63] = 'r';

	KUNIT_EXPECT_EQ(test, strncasecmp(s1, s2, 63), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(s1, s2, 64), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(s1, s2, 65), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(s2, s1, 64), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(s1, s1, 65), 0);
}

/* Mismatch in the first position only. */
static void agent_strncasecmp_first_char(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("Axxxx", "bxxxx", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("bxxxx", "Axxxx", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Axxxx", "axxxx", 5), 0);
}

/* Antisymmetry: swapping arguments flips the sign. */
static void agent_strncasecmp_antisymmetric(struct kunit *test)
{
	const char *pairs[][2] = {
		{ "abc", "ABD" }, { "Hello", "help" }, { "", "x" }, { "zz", "z" },
	};
	size_t i;

	for (i = 0; i < ARRAY_SIZE(pairs); i++) {
		int fwd = strncasecmp(pairs[i][0], pairs[i][1], 8);
		int rev = strncasecmp(pairs[i][1], pairs[i][0], 8);

		KUNIT_EXPECT_NE(test, fwd, 0);
		KUNIT_EXPECT_EQ(test, (fwd > 0) - (fwd < 0), -((rev > 0) - (rev < 0)));
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_strncasecmp_zero_len),
	KUNIT_CASE(agent_strncasecmp_identical),
	KUNIT_CASE(agent_strncasecmp_case_insensitive_equal),
	KUNIT_CASE(agent_strncasecmp_ordering),
	KUNIT_CASE(agent_strncasecmp_exact_difference),
	KUNIT_CASE(agent_strncasecmp_len_limits_compare),
	KUNIT_CASE(agent_strncasecmp_len_boundary),
	KUNIT_CASE(agent_strncasecmp_prefix),
	KUNIT_CASE(agent_strncasecmp_empty_strings),
	KUNIT_CASE(agent_strncasecmp_embedded_nul),
	KUNIT_CASE(agent_strncasecmp_non_letters),
	KUNIT_CASE(agent_strncasecmp_high_bytes),
	KUNIT_CASE(agent_strncasecmp_long_boundary),
	KUNIT_CASE(agent_strncasecmp_first_char),
	KUNIT_CASE(agent_strncasecmp_antisymmetric),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_LICENSE("GPL");
